otores_19":{"ed":"regioes","reg":"mg","t":"Prefeitura de BH regulamenta circulação de ciclomotores, bicicletas elétricas e patinetes","sub":"As novas regras classificam cada tipo de veículo, incluindo skates, e definem como cada um pode circular na capital.","hora":"18/11","pts":1.5},"isolados_ma_18":{"ed":"regioes","reg":"ne","t":"Cerca de 15 indígenas isolados Awá-Guajá aparecem perto de aldeia no Maranhão; Funai monta barreira sanitária","sub":"Guajajara da Terra Indígena Arariboia relatam o encontro; a Funai mobilizou barreira sanitária.","hora":"18/11","pts":1.5},"raoni_lula_visita_18":{"ed":"regioes","reg":"co","t":"Lula participa nesta quinta da homologação de terra indígena onde cresceu o cacique Raoni","sub":"Evento é nesta quinta (19), em Mato Grosso; Raoni, de 94 anos, luta pela demarcação desde a década de 1980.","hora":"19/11","pts":1.5},"ucrania_paz_19":{"ed":"mundo","reg":"","t":"Europeus devem participar da próxima rodada de negociações entre Ucrânia e Rússia, diz Zelensky","sub":"Putin manteve exigências para encerrar a guerra em reunião com enviados dos EUA; o território é o foco da próxima etapa.","hora":"18/11","pts":6.5,"resumo":"O presidente ucraniano, Volodymyr Zelensky, disse que a Europa vai participar da próxima rodada de negociações com a Rússia. Em reunião com enviados dos EUA, Vladimir Putin manteve as exigências para encerrar a guerra. Zelensky afirma que a questão territorial é o foco da próxima etapa."},"bukele_haiti_18":{"ed":"mundo","reg":"","t":"Bukele divulga vídeo de helicóptero bombardeando mansão no Haiti e diz que casa era de chefe de gangue","sub":"Cerca de dois mil militares salvadorenhos estão na ilha; Bukele nega que a operação busque riquezas do Haiti.","hora":"18/11","pts":3.5,"resumo":"O presidente de El Salvador, Nayib Bukele, divulgou vídeo de um helicóptero bombardeando uma mansão no Haiti e disse que o imóvel pertencia a um chefe de gangue. Ele afirma que a operação resgatou quatro soldados salvadorenhos capturados 